changeSet.sql:
			CREATE TABLE if not exists kb_signed_file (
				id					bigint primary key,
				resource_id			bigint,
				signature_id		bigint,
				date				timestamp with time zone DEFAULT now()
			);

			ALTER TABLE ONLY kb_signed_file DROP CONSTRAINT IF exists signature_signed_file_fk;
			ALTER TABLE ONLY kb_signed_file DROP CONSTRAINT IF exists file_signed_file_fk;

			ALTER TABLE kb_signed_file
				ADD CONSTRAINT signature_signed_file_fk FOREIGN KEY (signature_id) REFERENCES kb_signature (id) 
				MATCH SIMPLE
    			ON UPDATE NO ACTION
    			ON DELETE RESTRICT;

    		ALTER TABLE kb_signed_file
				ADD CONSTRAINT file_signed_file_fk FOREIGN KEY (resource_id) REFERENCES kfile (resource_id) 
				MATCH SIMPLE
    			ON UPDATE NO ACTION
    			ON DELETE CASCADE;

			alter table kb_signed_data add column if not exists device_id bigint;
			ALTER TABLE ONLY kb_signed_data DROP CONSTRAINT IF exists signed_device_fk;
    		ALTER TABLE kb_signed_data
				ADD CONSTRAINT signed_device_fk FOREIGN KEY (device_id) REFERENCES kb_device (id) 
				MATCH SIMPLE
    			ON UPDATE NO ACTION
    			ON DELETE RESTRICT;

alter table wf_procedure add column if not exists contenttemplate_id bigint;
ALTER TABLE wf_procedure ADD COLUMN if not exists type integer DEFAULT 1;
ALTER TABLE ONLY wf_procedure DROP CONSTRAINT IF exists contenttemplate_fk;

			CREATE TABLE if not exists kb_member_parent (
				member_id		bigint,
				parent_id		bigint
			);

			ALTER TABLE ONLY kb_member_parent DROP CONSTRAINT IF exists member_parent_member_fk;

			ALTER TABLE kb_member_parent
				ADD CONSTRAINT member_parent_member_fk FOREIGN KEY (member_id) REFERENCES datasetmember (id) 
				MATCH SIMPLE
    			ON UPDATE NO ACTION 
    			ON DELETE CASCADE;

			CREATE TABLE if not exists kb_member_security_rule (
				rule_id			bigint primary key,
				member_id		bigint
			);

			ALTER TABLE ONLY kb_member_security_rule DROP CONSTRAINT IF exists member_security_rule_fk;

			ALTER TABLE kb_member_security_rule
				ADD CONSTRAINT member_security_rule_fk FOREIGN KEY (member_id) REFERENCES datasetmember (id) 
				MATCH SIMPLE
    			ON UPDATE NO ACTION 
    			ON DELETE CASCADE;

create table kb_dictionary(
	id bigint primary key,
	locale varchar(50),
	state integer,
	domain_id bigint,
	lastModifiedDate timestamp with time zone,
	lastModifiedUser bigint,
	creationDate timestamp with time zone
);

ALTER TABLE kb_dictionary ADD CONSTRAINT fk_dictionary_domain FOREIGN KEY (domain_id) REFERENCES domain(id) on delete cascade;
ALTER TABLE kb_dictionary ADD CONSTRAINT fk_dictionary_user FOREIGN KEY (lastModifiedUser) REFERENCES users(id);

create table kb_dictionary_entry(
	id bigint primary key,
	dictionary_id bigint,
	key character varying (256),
	value character varying (256)
);

ALTER TABLE kb_dictionary_entry ADD CONSTRAINT fk_dictionary_entry_dictionary FOREIGN KEY (dictionary_id) REFERENCES kb_dictionary(id) on delete cascade;

			ALTER  TABLE kb_replica add column (
				localdomain_id   bigint;
 			);

			ALTER  TABLE kb_replica add column if not exists (
			standbyreplica_id character varying(20)
 			);

    create table kb_content_link (
			id bigint primary key,
			source_id bigint,
			target_id bigint,
			anchor	character varying (256),
			resource_id bigint,
			lastModifiedDate timestamp with time zone,
			lastModifiedUser bigint
		);	
			ALTER TABLE kb_content_link ADD CONSTRAINT fk_link_source FOREIGN KEY (source_id) REFERENCES content(id) on delete cascade;
			ALTER TABLE kb_content_link ADD CONSTRAINT fk_link_target FOREIGN KEY (target_id) REFERENCES content(id) on delete cascade;
			ALTER TABLE kb_content_link ADD CONSTRAINT fk_link_resource FOREIGN KEY (resource_id) REFERENCES kresource(id) on delete cascade;
			ALTER TABLE kb_content_link ADD CONSTRAINT fk_link_user FOREIGN KEY (lastModifiedUser) REFERENCES users(id);

    create table if not exists kb_content_proxy (
		id bigint primary key,
		content_id bigint,
		workspace bigint,
		locked boolean
	);

alter table Kb_Action_Rule drop column if exists contentoid;
alter table Kb_Action_Rule add column contentoid bigint;
alter table Kb_Action_Rule add column if not exists isContentRule boolean default false;
